/*
 * Host harness for the 0xF4 mirror packet. extracted_packet.c is copied VERBATIM from
 * app/src/mirror_notifier.c by run.sh.
 */
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "extracted_packet.c" /* generated by run.sh */

#define REPORT 32
static int failures;

static void expect(const char *name, bool oneshot, uint8_t id, uint32_t layers,
                   const uint8_t want8[8]) {
    uint8_t payload[MIRROR_NOTIFIER_LEN], buf[REPORT];
    memset(buf, 0xAA, sizeof(buf)); /* padding must be cleared */
    mirror_notifier_fill(payload, oneshot, id, layers);
    mirror_notifier_packet(buf, sizeof(buf), payload);
    bool ok = memcmp(buf, want8, 8) == 0;
    for (int i = 8; i < REPORT; i++) {
        ok = ok && buf[i] == 0;
    }
    printf("%-26s", name);
    for (int i = 0; i < 8; i++) {
        printf(" %02X", buf[i]);
    }
    printf("  %s\n", ok ? "ok" : "FAIL");
    failures += !ok;
}

/* The overlay's rule (MIRROR_PACKET_0xF4.md): mirrored = id != 0 && bit L of the mask. */
static bool overlay_mirrored(const uint8_t *buf, int top_layer) {
    uint32_t mask = buf[4] | (buf[5] << 8) | (buf[6] << 16) | ((uint32_t)buf[7] << 24);
    return buf[3] != 0 && ((mask >> top_layer) & 1);
}

int main(void) {
    expect("off", false, 0, 0, (const uint8_t[]){0xF4, 6, 0x00, 0, 0x00, 0x00, 0x00, 0x00});
    expect("id 1, layers 1 and 2", false, 1, 0x00000006,
           (const uint8_t[]){0xF4, 6, 0x00, 1, 0x06, 0x00, 0x00, 0x00});
    expect("one-shot, id 2, layers 0,31", true, 2, 0x80000001,
           (const uint8_t[]){0xF4, 6, 0x01, 2, 0x01, 0x00, 0x00, 0x80});
    expect("id 255, layers 8..23", false, 255, 0x00FFFF00,
           (const uint8_t[]){0xF4, 6, 0x00, 255, 0x00, 0xFF, 0xFF, 0x00});

    uint8_t payload[MIRROR_NOTIFIER_LEN], buf[REPORT];
    mirror_notifier_fill(payload, false, 3, (1u << 5) | (1u << 27));
    mirror_notifier_packet(buf, sizeof(buf), payload);
    bool dec = overlay_mirrored(buf, 5) && overlay_mirrored(buf, 27) && !overlay_mirrored(buf, 6) &&
               !overlay_mirrored(buf, 0);
    mirror_notifier_fill(payload, false, 0, 0);
    mirror_notifier_packet(buf, sizeof(buf), payload);
    dec = dec && !overlay_mirrored(buf, 5);
    printf("%-26s %s\n", "overlay decode rule", dec ? "ok" : "FAIL");
    failures += !dec;

    printf(failures ? "mirror-notifier: %d FAILED\n" : "mirror-notifier: all checks passed\n",
           failures);
    return failures != 0;
}
